WITH RECURSIVE menu AS ( SELECT MENU_CODE , MENU_TITLE , MENU_TITLE AS MENU_GNB , DEL_YN FROM TB_MENU WHERE MENU_CODE = 'ROOT'
UNION ALL
SELECT m.MENU_CODE , m.MENU_TITLE , concat(menu.MENU_GNB, ' > ', m.MENU_TITLE) AS MENU_GNB , m.DEL_YN FROM TB_MENU m JOIN menu ON m.MENU_PARENT = menu.MENU_CODE ) SELECT MENU_CODE , MENU_TITLE , MENU_GNB FROM menu WHERE MENU_CODE = #{value}

mapper.update:
UPDATE TB_MENU
   SET MENU_SEQ = #{MENU_SEQ}
      ,MENU_TITLE = #{MENU_TITLE}
      ,MENU_URL = #{MENU_URL}
      ,MENU_PARENT = #{MENU_PARENT}
      ,DEL_YN = #{DEL_YN}
WHERE MENU_CODE = #{MENU_CODE}
